import numpy as np
def equation(t, x, v, params):
    w=0.312
    return (params[0] + params[1]*v + params[2]*np.sqrt(v)*np.exp(-x) + params[3]*np.sqrt(v)
            + params[4]*v*v + params[5]*x + params[6]*np.log(x) + params[7]*v*np.log(x)
            + params[8]*np.cos(w*t) + params[9]*np.sin(w*t))
